import lazyload from "@/utils/lazyload";
import React, { useEffect, useMemo, useRef } from "react";
import { Redirect, Route, Switch } from "react-router-dom";
import { DorpTree } from '@/components/custom';
import _ from 'lodash';
import classNames from 'classnames';
import styles from './style.module.less';
import store from './store';
import { observer } from 'mobx-react-lite';
import '../document/style.less';
import { IconCopy, IconDelete, IconEdit, IconFile, IconFolder, IconMoreVertical, IconPlus } from '@arco-design/web-react/icon';
import { Button, Layout, Card, Link, ResizeBox, Space, Collapse, Tag, Form, Result, Modal, Menu, Dropdown, Empty, Message } from '@arco-design/web-react';
import { JSONSchemaCustom, SchemaForm } from "@/components/schema";
import ajax from "@/utils/ajax";
import { toJS } from 'mobx';
import EditDocument from "./components/EditDocument";

const Sider = Layout.Sider;
const Header = Layout.Header;
const Footer = Layout.Footer;
const Content = Layout.Content;
const { SubMenu, ItemGroup } = Menu;
const MenuItem = Menu.Item;

const Document = () => {

    const flattenRoutes = [];
    const defaultRoute = "";

    const routeChildren = useMemo(() => {
        return flattenRoutes.map((route, index) => {
          return (
            <Route
              key={index}
              path={`/${route.key}`}
              component={route.component}
            />
          );
        })
    },[flattenRoutes])

    const [form] = Form.useForm();

    useEffect(() => {
        store.getList();
    },[])

    const ref = useRef<any>();

    
    const schema = useMemo(() => {
        return {
            "type": "object",
            "properties": {
                "name": {
                    "title": "名称",
                    "type": "string"
                },
                "sort":{
                    "type": "number",
                    "title": "排序"
                },
                "type": {
                    "title": "类型",
                    "format": "radio",
                    "enum": [
                        { value: "directory", label: "目录" },
                        { value: "file", label: "文件" }
                    ],
                    "show": {
                        isMode: true,
                    },
                    default: "file"
                },
                "isShow": {
                    "type": "number",
                    "title": "是否显示",
                    "format": "radio",
                    "enum": [
                        { value: 1, label: "显示" },
                        { value: 0, label: "隐藏" },
                    ],
                    default: 1,
                }
            },
            required: ['name', 'mode', 'sort']
        } as JSONSchemaCustom
    },[])

    useEffect(() => {
        const result = store.list.filter((o) => o.type == "file")
        if(!result.find((o) => o.id == store.select)){
            if(store.list[0]){
                store.setSelect(result[0].id);
            }
        }
    },[store.list])

    useEffect(() => {
        if(store.initValue){
            form.clearFields();
        }
    },[store.initValue])


    
    return (
        <div className={classNames(styles.pages, 'layout-basic-document')}>
            <Layout style={{ height: '100%' }}>
                <Sider
                    resizeDirections={['right']}
                    style={{
                        minWidth: 120,
                        maxWidth: 500,
                    }}
                >
                    <DorpTree
                        value={store.treeList}
                        selectedKeys={[store.select]}
                        onSelect={(keys, extra) => {
                            const item = extra.node.props.dataRef as any;
                            if(item.type === "file"){
                                if(keys[0] !== store.select && ref.current){
                                    ref.current.changeDocument().then(() => {
                                        store.onSelect(keys);
                                    })
                                }
                            }else {
                                store.saveExpandedKeys(item)
                            }
                        }}
                        draggable={false}
                        fieldNames={{
                            key: "id",
                            title: "name"
                        }}
                        expandedKeys={store.expandedList}
                        onExpand={store.setExpandedKeys}
                        className={styles.treeItem}
                        renderTitle={(node: any) => {
                            const item: any = node.dataRef;
                            const isDst = item.type == "directory";
                            const menuList = (
                                <Menu
                                    onClick={(e) => {
                                        e.stopPropagation();
                                        e.preventDefault();
                                    }}
                                >
                                    <Menu.Item key="create"
                                        onClick={() => {
                                            console.log('item', item);
                                            store.setInitValue(_.omit(item, ['children']));
                                        }}
                                    >
                                        <IconEdit /> 编辑
                                    </Menu.Item>
                                    {isDst && (
                                        <Menu.Item key="categor" disabled={Boolean(node.parentId)}
                                            onClick={() => {
                                                store.setInitValue({ type: "directory", parentId: item.id })
                                            }}
                                        >
                                            <IconPlus /> 新增章节
                                        </Menu.Item>
                                    )}
                                    {isDst && (
                                         <Menu.Item key="api" disabled={item.type === "menu"}
                                            onClick={() => {
                                                store.setInitValue({ type: "file", parentId: item.id })
                                            }}
                                        >
                                            <IconPlus /> 新增文档
                                        </Menu.Item>
                                    )}
                                    <Menu.Item key='del'
                                        onClick={() => store.deleteNode(item)}
                                    >
                                        <IconDelete /> 删除
                                    </Menu.Item>
                                </Menu>
                            )

                            return (
                                <div className={styles.treeItemTitle} >
                                    <span>
                                        {item.type === "directory" && <IconFolder />}
                                        {item.type === "file" && <IconFile />}
                                        <span className={styles.titleText}>{node.title}</span>
                                        {item.isShow == 0 && <Tag color='red' size="small" style={{ marginLeft: 8 }} >已隐藏</Tag>}
                                    </span>
                                    <Dropdown  droplist={menuList} position='bl' trigger="click">
                                        <Button size="small" icon={<IconMoreVertical />} 
                                            onClick={(e) => {
                                                e.stopPropagation();
                                                e.preventDefault();
                                            }}
                                        />
                                    </Dropdown>
                                </div>
                            )
                        }}
                    />
                    <Button
                        style={{ margin: 16 }}
                        onClick={() => {
                            store.setInitValue({ isMode: true, mode: "directory" });
                        }}
                    >新建章节</Button>
                </Sider>
                <Content>
                    {store.select? <EditDocument ref={ref} id={store.select} /> : <Empty />}
                </Content>
            </Layout>
            <Modal title={store.title}
                unmountOnExit
                visible={Boolean(store.initValue)}
                onOk={() => {
                    form.validate().then((data) => {
                        const { id, type, parentId } = store.initValue;
                        if(id){
                            ajax.post('/apijson/put', {
                                Chapter: {
                                    ...data,
                                    id
                                }
                            }).then((res) => {
                                Message.success("更新成功");
                                store.setInitValue(null);
                                store.getList();
                            })
                        }else {
                            console.log('initValue', store.initValue, data);
                            ajax.post('/apijson/post', {
                                Chapter: {
                                    type,
                                    parentId,
                                    ...data
                                }
                            }).then((res) => {
                                Message.success("创建成功");
                                store.setInitValue(null)
                                store.getList();
                            })
                        }
                    })
                }}
                onCancel={() => {
                    store.setInitValue(null);
                }}
            >
                <SchemaForm
                    schema={schema}
                    form={form}
                    generagteProps={{
                        cols: 24
                    }}
                    wrapperCol={{ span: 16 }}
                    initialValues={store.initValue}
                ></SchemaForm>
            </Modal>

        </div>
    )
}

export default observer(Document);