import EditMarkdown from "@/components/markdown/EditMarkdown";
import { AsyncButton } from "@/components/custom";
import ajax from "@/utils/ajax";
import { Space, Spin, Message, Modal } from "@arco-design/web-react";
import { action, computed, observable, makeObservable } from 'mobx';
import { useObserver } from 'mobx-react-lite';
import React, { forwardRef, useImperativeHandle, useMemo, useState } from "react";

class DocStore{
    uid: string = "";


    @observable data: any;
    @action setData = (data) => {
        this.data = data;
    }

    get text(){
        return this.data? this.data.content : "";
    };

    @observable loading = true;
    @action
    setLoading = (bool) => {
        this.loading = bool;
    }
    
    @observable value = "";
    @action setValue = (val) => {
        this.value = val;
    }

    @computed get isSave(){
        return this.value != this.text;
    }

    getData = () => {
        ajax.post('/apijson/get', {
            ChapterDetail: {
                aid: this.uid,
            }
        }).then((res) => {
            this.setData(res.ChapterDetail);
            if(this.data){
                this.setValue(this.data.content);
            }
        }).finally(() =>{ 
            this.setLoading(false);
        })
    }

    saveData = () => {
        const data = {
            aid: this.uid,
            content: this.value,
        }
        return ajax.post(`/apijson/${this.data? 'put' : 'post'}`, {
            ChapterDetail: data,
        }).then((res) => {
            this.setData(data)
            Message.success("保存成功");
        })
    }

    constructor(id){
        makeObservable(this);
        this.uid = id;
        this.getData();
    }

}

interface EditDocumentProps {
    id: string;
}

const EditDocument = forwardRef(({id}: EditDocumentProps, ref) => {

    const docStore = useMemo(() => new DocStore(id), [id]);

    useImperativeHandle(ref,() => {
        return {
            changeDocument: () => {
                return new Promise((resolve, reject) => {
                    if(docStore.isSave){
                        Modal.confirm({
                            title: "当前文档未保存",
                            content: "是否放弃当前修改信息",
                            onCancel: reject,
                            onOk: resolve,
                        })
                    }else {
                        resolve(true);
                    }
                })
            }
        }
    },[docStore])

    return useObserver(() => {

        return (
            <div style={{ height: "100%", display: "flex", flexDirection: "column" }}>
                <Space style={{ justifyContent: "flex-end", padding: "4px 12px" }}>
                    <AsyncButton
                        type="primary" disabled={!docStore.isSave}
                        onClick={docStore.saveData}
                    >保存</AsyncButton>
                </Space>
                <div style={{ flex: 2 }}>
                    {/* {docStore.loading? <Spin dot loading style={{ display: 'block' }} /> */}
                    {/* :( */}
                        <EditMarkdown
                            value={docStore.value}
                            onChange={docStore.setValue}
                        />
                    {/* )} */}
                </div>
            </div>
        )
    })
})

export default EditDocument;