import React from "react";
import { observable, action, computed, toJS, makeObservable } from 'mobx';
import ajax from "@/utils/ajax";
import { Message, Modal } from "@arco-design/web-react";
import { convertToTree } from "@/utils";

class Store {
    @observable list = [];
    @action
    setList = (data) => {
        this.list = data;
    }

    constructor() {
        makeObservable(this);
    }

    @computed get treeList(){
        return convertToTree(toJS(this.list));
    }

    getList = () => {
        ajax.post('/apijson/get', {
            "Chapter[]": {
                "count": 0,
                "Chapter": {
                    "@column": "id, type, name, sort, parentId, isShow",
                    "@order": "sort+"
                }
            }
        }).then((res) => {
            this.setList(res.Chapter);
        })
    }

    @observable select = "";
    @action setSelect = (id) => {
        this.select = id;
    }
    @action onSelect = (list) => {
        this.select = list[0];
    }

    @observable expandedKeys: string[] = [];
    @action
    setExpandedKeys = (list) => {
        this.expandedKeys = list;
    }
    @computed get expandedList(){
        return toJS(this.expandedKeys);
    }

    @observable initValue: any = null;
    @action setInitValue = (val) => {
        this.initValue = val;
    }

    @computed get title() {
        if(this.initValue){
            return `${this.initValue.id? "编辑" : "新增"}章节`;
        }
        return ""
    }


    addExpandedKeys = (item) => {
        this.setExpandedKeys([...this.expandedList, item.id])
    }

    saveExpandedKeys = (item) => {
        if(this.expandedList.find((o) => o == item.id)){
            this.setExpandedKeys(this.expandedList.filter((o) => o != item.id));                                
        }else {
            this.addExpandedKeys(item)
        }
    }

    /**
     * 删除章节
     */
    deleteNode = (menu: any) => {
        if(menu.children && menu.children.length){
            return Message.warning("请先删除当前章节下其他内容")
        }
        Modal.confirm({
            title: `请确认删除章节【${menu.name}】`,
            onOk: () => {
                let params = { "Chapter": { id: menu.id } }
                if(menu.type === "file") params["ChapterDetail"] = { aid: menu.pageId };
                ajax.post("/apijson/delete", params).then((res) => {
                    Message.success("删除成功");
                    this.getList();
                })
            }
        })
    }
}

export default new Store();